    24	@Service
    25	public class PedidoService {
    26	
    27	    private static final Duration PRAZO_PAGAMENTO = Duration.ofHours(48);
    28	
    29	    private final Checkout checkout;
    30	    private final PedidoRepository pedidos;
    31	    private final ClienteRepository clientes;
    32	    private final List<AcaoPedido> acoes;
    33	    private final TransactionTemplate tx;
    34	    private final Clock clock;
    35	
    36	    public PedidoService(Checkout checkout, PedidoRepository pedidos, ClienteRepository clientes,
    37	            List<AcaoPedido> acoes, TransactionTemplate tx, Clock clock) {
    38	        this.checkout = checkout;
    39	        this.pedidos = pedidos;
    40	        this.clientes = clientes;
    41	        this.acoes = acoes;
    42	        this.tx = tx;
    43	        this.clock = clock;
    44	    }
    45	
    46	    public Resumo resumo(PedidoRequest req) {
    47	        return checkout.calcular(req);
    48	    }
    49	
    50	    public Pedido registrar(PedidoRequest req) {
    51	        Resumo resumo = checkout.calcular(req);
    52	        Pedido pedido = new Pedido(UUID.randomUUID().toString(), req.cliente().cpf(), req.cliente().email(),
    53	                Situacao.AGUARDANDO_PAGAMENTO, Instant.now(clock).truncatedTo(ChronoUnit.SECONDS), resumo,
    54	                req.itens().stream().map(i -> new ItemPedido(i.sku(), i.quantidade())).toList(), null, null);
    55	        tx.executeWithoutResult(s -> {
    56	            Object ponto = s.createSavepoint();
    57	            try {
    58	                clientes.criarSeNaoExiste(pedido.cpf(), pedido.email());
    59	                s.releaseSavepoint(ponto);
    60	            } catch (DuplicateKeyException e) {
    61	                s.rollbackToSavepoint(ponto);
    62	            }
    63	            pedidos.inserir(pedido);
    64	        });
    65	        return pedido;
    66	    }
    67	
    68	    public Pedido consultar(String id) {
    69	        return pedidos.buscar(id).orElseThrow(() -> NegocioException.naoEncontrado("PEDIDO_NAO_ENCONTRADO"));
    70	    }
    71	
    72	    private record Resultado(Pedido pedido, NegocioException erro) {
    73	    }
    74	
    75	    public Pedido pagar(String id, String idTransacao, String pagoEmTexto) {
    76	        Resultado r = tx.execute(status -> {
    77	            Pedido p = travar(id);
    78	            if (idTransacao == null || idTransacao.isBlank()) {
    79	                throw NegocioException.invalido("PEDIDO_INVALIDO");
    80	            }
    81	            Instant pagoEm = parseData(pagoEmTexto);
    82	            if (p.situacao() != Situacao.AGUARDANDO_PAGAMENTO) {
    83	                if (p.situacao().pagoEAtivo() && idTransacao.equals(p.idTransacao())) {
    84	                    return new Resultado(p, null);
    85	                }
    86	                throw NegocioException.conflito("OPERACAO_NAO_PERMITIDA");
    87	            }
    88	            if (Duration.between(p.criadoEm(), pagoEm).compareTo(PRAZO_PAGAMENTO) > 0) {
    89	                cancelarEAvisar(p, false);
    90	                return new Resultado(null, NegocioException.conflito("PEDIDO_EXPIRADO"));
    91	            }
    92	            Object ponto = status.createSavepoint();
    93	            try {
    94	                pedidos.registrarPagamento(id, idTransacao);
    95	                acoes.forEach(a -> a.aoPagar(p));
    96	                status.releaseSavepoint(ponto);
    97	            } catch (NegocioException e) {
    98	                status.rollbackToSavepoint(ponto);
    99	                cancelarEAvisar(p, false);
   100	                return new Resultado(null, e);
   101	            }
   102	            return new Resultado(pedidos.buscar(id).orElseThrow(), null);
   103	        });
   104	        if (r.erro() != null) {
   105	            throw r.erro();
   106	        }
   107	        return r.pedido();
   108	    }
   109	
   110	    public Pedido enviar(String id, String codigoRastreio) {
   111	        return tx.execute(status -> {
   112	            Pedido p = travar(id);
   113	            exigir(p, Situacao.ENVIADO);
   114	            if (codigoRastreio == null || codigoRastreio.isBlank()) {
   115	                throw NegocioException.invalido("PEDIDO_INVALIDO");
   116	            }
   117	            pedidos.registrarEnvio(id, codigoRastreio);
   118	            return pedidos.buscar(id).orElseThrow();
   119	        });
   120	    }
   121	
   122	    public Pedido entregar(String id) {
   123	        return tx.execute(status -> {
   124	            Pedido p = travar(id);
   125	            exigir(p, Situacao.ENTREGUE);
   126	            pedidos.atualizarSituacao(id, Situacao.ENTREGUE);
   127	            return pedidos.buscar(id).orElseThrow();
   128	        });
   129	    }
   130	
   131	    public Pedido cancelar(String id) {
   132	        return tx.execute(status -> {
   133	            Pedido p = travar(id);
   134	            exigir(p, Situacao.CANCELADO);
   135	            cancelarEAvisar(p, p.situacao() != Situacao.AGUARDANDO_PAGAMENTO);
   136	            return pedidos.buscar(id).orElseThrow();
   137	        });
   138	    }
   139	
   140	    private void cancelarEAvisar(Pedido p, boolean estavaPago) {
   141	        pedidos.atualizarSituacao(p.id(), Situacao.CANCELADO);
   142	        acoes.forEach(a -> a.aoCancelar(p, estavaPago));
   143	    }
   144	
   145	    private Pedido travar(String id) {
   146	        return pedidos.buscarParaAtualizar(id)
   147	                .orElseThrow(() -> NegocioException.naoEncontrado("PEDIDO_NAO_ENCONTRADO"));
   148	    }
   149	
   150	    private static void exigir(Pedido p, Situacao destino) {
   151	        if (!p.situacao().podeIr(destino)) {
   152	            throw NegocioException.conflito("OPERACAO_NAO_PERMITIDA");
   153	        }
   154	    }
   155	
   156	    private Instant parseData(String texto) {
   157	        if (texto == null || texto.isBlank()) {
   158	            return Instant.now(clock);
   159	        }
   160	        try {
   161	            return Instant.parse(texto);
   162	        } catch (DateTimeParseException e) {
   163	            throw NegocioException.invalido("PEDIDO_INVALIDO");
   164	        }
   165	    }
   166	}

