    51	    private Optional<Pedido> buscar(String id, boolean travar) {
    52	        String sql = "SELECT * FROM pedido WHERE id = ?" + (travar ? " FOR UPDATE" : "");
    53	        return jdbc.sql(sql).param(id).query((rs, n) -> {
    54	            Instant criado = rs.getObject("criado_em", LocalDateTime.class).toInstant(ZoneOffset.UTC);
    55	            return new Pedido(rs.getString("id"), rs.getString("cpf"), rs.getString("email"),
    56	                    Situacao.valueOf(rs.getString("situacao")), criado,
    57	                    mapper.readValue(rs.getString("resumo"), Resumo.class), List.of(),
    58	                    rs.getString("codigo_rastreio"), rs.getString("id_transacao"));
    59	        }).optional().map(p -> new Pedido(p.id(), p.cpf(), p.email(), p.situacao(), p.criadoEm(), p.resumo(),
    60	                itens(p.id()), p.codigoRastreio(), p.idTransacao()));
    61	    }
